-- Guests
CREATE INDEX IF NOT EXISTS idx_guests_assigned_table ON guests (assigned_table);

-- Relationships
CREATE INDEX IF NOT EXISTS idx_relationships_guest_a ON relationships (guest_a);
CREATE INDEX IF NOT EXISTS idx_relationships_guest_b ON relationships (guest_b);

